CREATE TABLE IF NOT EXISTS data_sources (id text PRIMARY KEY,name text NOT NULL,url text NOT NULL,official boolean NOT NULL DEFAULT false,retrieved_at timestamptz NOT NULL,license text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS courses (id text PRIMARY KEY,subject text NOT NULL,number text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',department text NOT NULL,units_min numeric NOT NULL,units_max numeric NOT NULL,level text,prerequisites jsonb NOT NULL DEFAULT '[]'::jsonb,requirement_tags jsonb NOT NULL DEFAULT '[]'::jsonb,cross_listings jsonb NOT NULL DEFAULT '[]'::jsonb,source_id text NOT NULL REFERENCES data_sources(id),updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS courses_code_idx ON courses(subject,number);
CREATE INDEX IF NOT EXISTS courses_department_idx ON courses(department);
CREATE TABLE IF NOT EXISTS sections (id text PRIMARY KEY,course_id text NOT NULL REFERENCES courses(id),term text NOT NULL,section_number text NOT NULL,component text,instructors jsonb NOT NULL DEFAULT '[]'::jsonb,meetings jsonb NOT NULL DEFAULT '[]'::jsonb,enrolled integer NOT NULL DEFAULT 0,capacity integer NOT NULL DEFAULT 0,waitlisted integer NOT NULL DEFAULT 0,waitlist_capacity integer NOT NULL DEFAULT 0,source_id text NOT NULL REFERENCES data_sources(id),updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sections_term_course_idx ON sections(term,course_id);
CREATE TABLE IF NOT EXISTS grade_distributions (id text PRIMARY KEY,course_id text NOT NULL REFERENCES courses(id),term text NOT NULL,instructor text NOT NULL,counts jsonb NOT NULL,mean numeric,median text,sample_size integer NOT NULL,source_id text NOT NULL REFERENCES data_sources(id),updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS grades_course_term_idx ON grade_distributions(course_id,term);
CREATE TABLE IF NOT EXISTS enrollment_snapshots (section_id text NOT NULL REFERENCES sections(id),observed_at timestamptz NOT NULL,enrolled integer NOT NULL,capacity integer NOT NULL,waitlisted integer NOT NULL,source_id text NOT NULL REFERENCES data_sources(id),PRIMARY KEY(section_id,observed_at));
CREATE INDEX IF NOT EXISTS enrollment_section_time_idx ON enrollment_snapshots(section_id,observed_at);
CREATE TABLE IF NOT EXISTS user_profiles (id text PRIMARY KEY,clerk_user_id text NOT NULL UNIQUE,email text,priorities jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS saved_plans (id text PRIMARY KEY,user_id text NOT NULL REFERENCES user_profiles(id),name text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS saved_plans_user_idx ON saved_plans(user_id);
